    pts6 = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 6]
    out = [row[:] for row in grid]
    for r, c in pts6:
        out[r][c] = 0
    if not pts4 or not pts6:
        return out
    # Reflect the 4-shape across the gap in the direction of the 6 marker.
    r4 = (min(r for r, c in pts4) + max(r for r, c in pts4)) / 2
    c4 = (min(c for r, c in pts4) + max(c for r, c in pts4)) / 2
    r6 = (min(r for r, c in pts6) + max(r for r, c in pts6)) / 2
    c6 = (min(c for r, c in pts6) + max(c for r, c in pts6)) / 2
    if abs(r6 - r4) >= abs(c6 - c4):
        # Horizontal reflection; axis is halfway between the nearest edges.
        if r6 > r4:
            axis2 = max(r for r, c in pts4) + min(r for r, c in pts6) - 1
